# Let me compute the distance-based fill
def compute_fill(input_grid, marker1_pos, marker2_pos, marker1_val=9, marker2_val=1):
    h, w = len(input_grid), len(input_grid[0])
    output = [row[:] for row in input_grid]
    # The wall is 5s at rows 2-7, cols 2-7
    # Fill interior: rows 3-6, cols 3-6

    for r in range(3, 7):
        for c in range(3, 7):
            d1 = abs(r - marker1_pos[0]) + abs(c - marker1_pos[1])
            d2 = abs(r - marker2_pos[0]) + abs(c - marker2_pos[1])

            # Using the value with smaller distance
            if d1 <= d2:
                output[r][c] = marker1_val
            else:
                output[r][c] = marker2_val
    return output

